versions.variantCss:
.wemd-accordion[data-variant="bytedance-accordion-card"] {
  margin: 16px 0;
}
.wemd-accordion[data-variant="bytedance-accordion-card"] .wemd-component-body {
  padding: 0;
}
.wemd-accordion[data-variant="bytedance-accordion-card"] .wemd-component-body .wemd-child-1,
.wemd-accordion[data-variant="bytedance-accordion-card"] .wemd-component-body .wemd-child-3 {
  color: var(--wemd-text-strong);
  font-size: 15px;
  font-weight: 700;
  margin: 0;
  padding: 12px 16px 12px 40px;
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  border-bottom: 2px solid var(--wemd-primary);
}
.wemd-accordion[data-variant="bytedance-accordion-card"] .wemd-component-body .wemd-child-2,
.wemd-accordion[data-variant="bytedance-accordion-card"] .wemd-component-body .wemd-child-4 {
  color: var(--wemd-text-normal);
  font-size: 14px;
  line-height: 1.75;
  margin: 8px 0 12px 0;
  padding: 0 16px;
}
